/*
 * The OpenAPI 3.1 document of the REST service, generated by a pure function from REST_ROUTES and the
 * schemas present() gives (presentedInput, presentedOutput), so the routes, the docs and the checks
 * cannot drift apart. The view's JSON Schema (pivotkit-core's view-2.json) is bundled into
 * components, so a client needs nothing from elsewhere. The committed copy (docs/openapi.json) is the
 * document of a server with static tokens; a running server serves its own at /openapi.json (its
 * address and its sign-in).
 */

import { createRequire } from "node:module";
import { OPERATIONS } from "pivotkit-report/operations";
import { RENDER_FORMATS } from "pivotkit-report";
import { REST_BASE } from "../config.js";
import { VERSION } from "../context.js";
import { presentedInput, presentedOutput } from "../present.js";
import { PROBLEM_CODES } from "./problem.js";
import { REST_ROUTES } from "./routes.js";

const require = createRequire(import.meta.url);

/** The statuses each kind of route can answer with besides 200, and why. */
const PROBLEMS = Object.freeze({
    400: "The input is not valid (INVALID_INPUT).",
    401: "No token, or one the service does not accept (INVALID_TOKEN).",
    403: "Not allowed: a scope missing, files by path, a host or origin refused.",
    404: "No such source or route.",
    409: "The server cannot do this: no output directory, no link page, not schedulable.",
    413: "A limit: the body, the file or the result is too large.",
    415: "The body is not JSON, or the file's format is not read.",
    422: "The file cannot be read, or (file route) the view has errors.",
    429: "Too many requests: wait as Retry-After says.",
    503: "Busy or not ready: try again as Retry-After says.",
    504: "The report took longer than the server allows."
});

/** "describe_source" as "DescribeSource". */
const pascal = (name) => name.replace(/(^|_)([a-z])/g, (_m, _s, c) => c.toUpperCase());

/** The view schema of pivotkit-core, as components: its $defs beside it, every $ref pointed there. */
function viewComponents() {
    const schema = structuredClone(require("pivotkit-core/schema/view-2.json"));
    const defs = schema.$defs ?? {};
    delete schema.$schema;
    delete schema.$id;
    delete schema.$defs;
    const rewrite = (node) => {
        if (Array.isArray(node)) {
            node.forEach(rewrite);
        } else if (node && typeof node === "object") {
            for (const [key, value] of Object.entries(node)) {
                if (key === "$ref" && typeof value === "string" && value.startsWith("#/$defs/")) {
                    node.$ref = `#/components/schemas/View_${value.slice("#/$defs/".length)}`;
                } else {
                    rewrite(value);
                }
            }
        }
        return node;
    };
    const out = { View: rewrite(schema) };
    for (const [name, def] of Object.entries(defs)) {
        out[`View_${name}`] = rewrite(def);
    }
    return out;
}

/** A view in an input: a view, a view file, or either as JSON text. */
const VIEW_INPUT = {
    description: "The view: a JSON object with rows, cols, values, filters, derived, sort, display; or a view file; or either as JSON text.",
    anyOf: [{ $ref: "#/components/schemas/View" }, { type: "object", description: "A view file (format pivotkit-view)." }, { type: "string", description: "A view or a view file as JSON text." }]
};

/** An operation's input schema with the view referenced. */
function inputSchema(name) {
    const schema = structuredClone(presentedInput(name, { files: false }));
    if (schema.properties?.view) {
        schema.properties.view = VIEW_INPUT;
    }
    return schema;
}

/**
 * @typedef {object} OpenApiOptions
 * @property {import("../config.js").AuthOptions} [auth]  the sign-in the document describes (default: static tokens)
 * @property {string} [publicUrl]  the server's address as clients reach it
 * @property {any} [issuer]  OAuth: the issuer's metadata (its endpoints)
 * @property {string} [resource]  OAuth: the REST resource
 * @property {string[]} [requiredScopes]  OAuth: the scopes every call needs
 */

/**
 * The OpenAPI 3.1 document.
 * @param {OpenApiOptions} [options]
 */
export function openApiDocument(options = {}) {
    const auth = options.auth ?? { mode: "token" };
    const mode = auth.mode ?? "none";
    const required = options.requiredScopes ?? auth.requiredScopes ?? [];
    /** @type {Record<string, any>} */
    const securitySchemes = {};
    if (mode === "token") {
        securitySchemes.bearer = { type: "http", scheme: "bearer", description: "A static token the operator gives you: Authorization: Bearer <token>." };
    } else if (mode === "oauth") {
        const issuer = options.issuer;
        const scopes = Object.fromEntries([...new Set([...required, ...Object.values(auth.toolScopes ?? {}).flat(), ...(auth.scopesSupported ?? [])])].map((s) => [s, `the scope ${s}`]));
        securitySchemes.oauth = issuer?.authorization_endpoint && issuer?.token_endpoint
            ? { type: "oauth2", description: `An access token of ${issuer.issuer} for the resource ${options.resource ?? REST_BASE}.`, flows: { authorizationCode: { authorizationUrl: issuer.authorization_endpoint, tokenUrl: issuer.token_endpoint, scopes } } }
            : { type: "openIdConnect", openIdConnectUrl: `${String(auth.issuer ?? "").replace(/\/$/, "")}/.well-known/openid-configuration`, description: `An access token for the resource ${options.resource ?? REST_BASE}.` };
    }
    const schemeName = Object.keys(securitySchemes)[0];
    const security = (route) => (schemeName ? [{ [schemeName]: mode === "oauth" ? [...required, ...(auth.toolScopes?.[route.operation] ?? [])] : [] }] : []);

    /** @type {Record<string, any>} */
    const schemas = {
        Problem: {
            type: "object",
            description: "An error (RFC 9457 problem details).",
            required: ["type", "title", "status", "code", "detail"],
            properties: {
                type: { type: "string", format: "uri", description: "The address that names the error's code." },
                title: { type: "string" },
                status: { type: "integer" },
                code: { enum: PROBLEM_CODES },
                detail: { type: "string", description: "What went wrong and what to do; never file content." },
                findings: { type: "array", items: { type: "object" }, description: "The view's findings (422 of the file route)." }
            }
        },
        ...viewComponents()
    };
    for (const name of Object.keys(OPERATIONS)) {
        schemas[`${pascal(name)}Input`] = inputSchema(name);
        schemas[`${pascal(name)}Output`] = presentedOutput(name);
    }
    /** @type {Record<string, any>} */
    const responses = {};
    for (const [status, description] of Object.entries(PROBLEMS)) {
        responses[`Problem${status}`] = { description, content: { "application/problem+json": { schema: { $ref: "#/components/schemas/Problem" } } } };
    }

    /** @type {Record<string, any>} */
    const paths = {};
    for (const route of REST_ROUTES) {
        const op = OPERATIONS[route.operation];
        const errors = route.method === "GET" && !route.path.includes("{") ? [401, 403, 429, 503] : [400, 401, 403, 404, 409, 413, 415, 422, 429, 503, 504];
        const okContent =
            route.answer === "file"
                ? Object.fromEntries(Object.values(RENDER_FORMATS).map((f) => [f.mediaType.split(";")[0], { schema: { type: "string", contentMediaType: f.mediaType.split(";")[0] } }]))
                : { "application/json": { schema: { $ref: `#/components/schemas/${pascal(route.operation)}Output` }, example: route.example.output } };
        paths[`${REST_BASE}${route.path}`] ??= {};
        paths[`${REST_BASE}${route.path}`][route.method.toLowerCase()] = {
            operationId: route.id,
            summary: route.summary,
            description: route.description,
            tags: [route.path.split("/")[1]],
            ...(schemeName ? { security: security(route) } : {}),
            ...(auth.toolScopes?.[route.operation]?.length ? { "x-pivotkit-scopes": auth.toolScopes[route.operation] } : {}),
            ...(route.path.includes("{id}") ? { parameters: [{ name: "id", in: "path", required: true, description: "A source id from GET /sources.", schema: { type: "string", minLength: 1, maxLength: 1024 } }] } : {}),
            ...(route.method === "POST" ? { requestBody: { required: true, content: { "application/json": { schema: { $ref: `#/components/schemas/${pascal(route.operation)}Input` }, example: route.example.input } } } } : {}),
            responses: {
                200: route.answer === "file" ? { description: `The file (${Object.keys(RENDER_FORMATS).join(", ")}), as an attachment.`, headers: { "Content-Disposition": { schema: { type: "string" } } }, content: okContent } : { description: op.title, content: okContent },
                ...Object.fromEntries(errors.map((s) => [s, { $ref: `#/components/responses/Problem${s}` }]))
            }
        };
    }

    return {
        openapi: "3.1.0",
        info: {
            title: "pivotkit REST",
            version: VERSION,
            summary: "Describe data sources, validate and render pivot views, make links and draft schedules.",
            description: "The operations of pivotkit's MCP server over HTTP for programs. Errors are RFC 9457 problem details. The routes are RPC-style (POST /views/validate); /api/v1 changes only with a breaking change. Docs: https://pivotkit.eize.dev/reference/rest/",
            license: { name: "MIT", identifier: "MIT" }
        },
        servers: [{ url: options.publicUrl ? new URL(REST_BASE, options.publicUrl).href : REST_BASE }],
        tags: [
            { name: "sources", description: "The data sources a caller may use." },
            { name: "views", description: "Views: the guide, validation, description, rendering and links." },
            { name: "schedules", description: "Drafts of scheduled reports for a person to approve." }
        ],
        paths,
        components: { schemas, responses, ...(schemeName ? { securitySchemes } : {}) }
    };
}
